function scanForInjection(text: string): {
  isSuspicious: boolean;
  flags: string[];
} {
  const flags: string[] = [];
  const lower = text.toLowerCase();

  const patterns = [
    'ignore previous instructions',
    'ignore all instructions',
    'you are now',
    'disregard everything above',
    'new instructions:',
    'override system',
    'jailbreak',
    'simulate',
    'pretend you are'
  ];

  for (const pattern of patterns) {
    if (lower.includes(pattern)) flags.push(pattern);
  }

  return {
    isSuspicious: flags.length > 0,
    flags
  };
}
